// Grille direction (0=horz, 1=vert)
#define DBM_V 0
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// Grille (0=monochome, 1=chromatic)
#define DBM_C 1
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// Brightness maximum
// Doing it here in DBM enables higher quality scanlines
// Doing it in BF2 instead reduces more ghosting
#define DBM_B (1.0-1.0/4.0)
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .
