//                              DBM SHADERTOY WRAPPER
//
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
// DBM does a fixed 2x2 up-sample, designed for flat panel displays
// See the DBM source in the middle for more information
// Cut that middle section out to use
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
// . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .
//. . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
//                              JUNKY DBM INTERFACE
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
// Used for emulation of sRGB->linear reads and for store
float SelF1(float a,float b,bool p){return p?b:a;}
bool GtF1(float a,float b){return a>b;}
// To sRGB
float SrgbEncF1(float c){vec3 j=vec3(0.0031308*12.92,12.92,1.0/2.4);
 vec2 k=vec2(1.055,-0.055);
 return clamp(j.x,c*j.y,pow(c,j.z)*k.x+k.y);}
// To linear
float SrgbDecF1(float c){vec3 j=vec3(0.04045,1.0/12.92,2.4);
 vec2 k=vec2(1.0/1.055,0.055/1.055);
 return SelF1(c*j.y,pow(c*k.x+k.y,j.z),GtF1(c,j.x));}
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
#define DBM_SHADERTOY 1
// This must return linear data (not perceptual) else algorithm won't work
vec3 DbmTex(vec2 p){vec3 c;
 #if 1
  // [DEBUG] For testing a scrolling texture
  p.x+=float(iFrame>>1)*SPEED;
 #endif
 c=textureLod(iChannel0,p,0.0).rgb;
 // Shadertoy lacks sRGB to linear, so must emulate that
 // Take this as an example of how not to do this fast
 c.x=SrgbDecF1(c.x);c.y=SrgbDecF1(c.y);c.z=SrgbDecF1(c.z);return c;}
