//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
//                              SHADERTOY ENTRY
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
void mainImage(out F4 fragColor,in F2 fragCoord){
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 // Setup compute shader emulation
 DbmI2 g=DbmI2(fragCoord);
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
 // Constants for DBM
 DbmF2 kRcp2Img   =vec2(1.0 )/(vec2(2.0)*vec2(textureSize(iChannel0,0)));
 DbmF2 kQutrRcpImg=vec2(0.25)/(vec2(1.0)*vec2(textureSize(iChannel0,0)));
 DbmF2 kHalfRcpImg=vec2(0.5 )/(vec2(1.0)*vec2(textureSize(iChannel0,0)));
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ 
 // Panels
 DbmF2 panel=DbmF2(iResolution.x*0.25,iResolution.x*0.75);
 DbmH4 c=DbmH4(0.0); 
 c.rgb=Dbm(g.xy,kRcp2Img,kHalfRcpImg,kQutrRcpImg);
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 // Shadertoy is OpenGL ES reversed Y (puke)
 F1 y=1.0-(fragCoord.y/iResolution.y);
 // Get the nearest timestamp in units of input frame count
 F1 t=F1(iFrame>>1);
 // Compute the sampling position
 F2 uv;
 uv=fragCoord.xy/iResolution.xy;
 // The right/left split
 P1 bf2=uv.x<0.5;
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 // Run filter
 H3 c0,c1;
 // Note the bright input is scaled by 2
 Bf2(c0,c1,c.rgb,I1(iFrame>>1),F1(CLEAN),H1(2.0*BRIGHT),H2(CHROMA,1.0-CHROMA),y);
//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~--~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
 // Select the correct output 
 // A real engine would just present both {c0,c1}
 // This shader toy just recomputes then selects the right output
 if(bf2)c.rgb=(iFrame&1)==0?c0:c1;else c.rgb*=H3(BRIGHT);
 // Convert back to sRGB 
 c.rgb=Bf2LinToSrgbH3(c.rgb);
 fragColor=F4(c.r,c.g,c.b,1.0);}
